contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test: deposit an amount into c and then call withdrawAll once
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract can fund the deposit
        require(address(this).balance >= depositAmount);

        // record C's balance before deposit
        uint beforeC = address(c).balance;

        // perform deposit of depositAmount into c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record C's balance immediately after deposit
        uint afterDepositC = address(c).balance;

        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record C's balance after withdraw attempt
        uint afterWithdrawC = address(c).balance;

        // General invariant asserted for all inputs:
        // - If withdrawAll reverted: C's balance must be at least what it was immediately after deposit (no net decrease).
        // - If withdrawAll returned: C's balance decreased by exactly the deposited amount.
        assert(
            reverted
            ? (afterWithdrawC >= afterDepositC)
            : (afterDepositC == beforeC + depositAmount && afterWithdrawC + depositAmount == afterDepositC)
        );
    }

    // accept Ether when C sends funds back to this test contract
    receive() external payable {}
}

